import time

def timer(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f'Took {end - start:.4f}s')
        return result
    return wrapper

@timer
def count():
    total = 0
    for i in range(1_000_000):
        total += i
    return total

print(count())

def repeat(n):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(n):
                func(*args, **kwargs)
        return wrapper
    return decorator

@repeat(3)
def say_hello():
    print('Hello!')

say_hello()

